    // owner is also treated as immutable
    owner = owner_;

    treasury = treasury_;
    emit TreasuryChanged(address(0), treasury_);

    _enableFeeAmount(100, 1, 5, 10);
    _enableFeeAmount(3000, 60, 5, 30);
    _enableFeeAmount(10000, 200, 15, 100);
